import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.em2JOrjF.js";const p=JSON.parse('{"title":"Logging Time","description":"","frontmatter":{},"headers":[],"relativePath":"reference/workflows/logging-time.md","filePath":"reference/workflows/logging-time.md"}'),n={name:"reference/workflows/logging-time.md"};function i(s,e,l,u,g,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="logging-time" tabindex="-1">Logging Time <a class="header-anchor" href="#logging-time" aria-label="Permalink to &quot;Logging Time&quot;">​</a></h1><p>How time gets from &quot;I worked on Nike today&quot; to a record in the database.</p><hr><h2 id="what-vera-needs" tabindex="-1">What VERA needs <a class="header-anchor" href="#what-vera-needs" aria-label="Permalink to &quot;What VERA needs&quot;">​</a></h2><p>Every time entry requires four things:</p><ol><li><strong>Who</strong> — you (or someone you&#39;re logging for)</li><li><strong>Project</strong> — which project the work belongs to</li><li><strong>Task</strong> — what type of work (Development, Design, QA, etc.)</li><li><strong>Hours</strong> — how much time, in <code>4h 30m</code> format</li></ol><p>Date defaults to today. Notes are optional.</p><hr><h2 id="basic-logging-as-a-user" tabindex="-1">Basic logging (as a User) <a class="header-anchor" href="#basic-logging-as-a-user" aria-label="Permalink to &quot;Basic logging (as a User)&quot;">​</a></h2><blockquote><p>&quot;Log 3 hours on Nike Rebrand for design&quot;</p></blockquote><p>VERA creates the entry and confirms:</p><blockquote><p>&quot;Logged 3h on Nike Rebrand (Design) (ID: 42)&quot;</p></blockquote><p>Save that ID — you&#39;ll need it if you want to edit or delete later.</p><hr><h2 id="what-happens-if-you-skip-the-task" tabindex="-1">What happens if you skip the task? <a class="header-anchor" href="#what-happens-if-you-skip-the-task" aria-label="Permalink to &quot;What happens if you skip the task?&quot;">​</a></h2><blockquote><p>&quot;3 hours on Nike Rebrand&quot;</p></blockquote><p>VERA will ask:</p><blockquote><p>&quot;What type of work? (Development, Design, QA, Project Management, Client Meeting, Admin)&quot;</p></blockquote><p>You must answer before VERA logs anything. Task is never skipped or defaulted.</p><hr><h2 id="logging-for-someone-else-manager-owner" tabindex="-1">Logging for someone else (Manager/Owner) <a class="header-anchor" href="#logging-for-someone-else-manager-owner" aria-label="Permalink to &quot;Logging for someone else (Manager/Owner)&quot;">​</a></h2><p>Managers can log time for team members on their assigned projects. Owners can log for anyone.</p><p><strong>By @mention (recommended):</strong></p><blockquote><p>&quot;Log 4h for @alice on Nike Rebrand — development&quot;</p></blockquote><p>Using the Slack @mention is more reliable than typing a name, because names can have variations.</p><p><strong>By name:</strong></p><blockquote><p>&quot;Log 2h for Alice on Nike Rebrand — QA&quot;</p></blockquote><hr><h2 id="specifying-a-past-date" tabindex="-1">Specifying a past date <a class="header-anchor" href="#specifying-a-past-date" aria-label="Permalink to &quot;Specifying a past date&quot;">​</a></h2><blockquote><p>&quot;Log 6h on Acme Website for development — yesterday&quot; &quot;Log 4h on Nike Rebrand for design on March 15&quot;</p></blockquote><p>Date format: <code>YYYY-MM-DD</code> or natural language. VERA resolves relative dates in the tenant&#39;s timezone.</p><hr><h2 id="editing-an-entry" tabindex="-1">Editing an entry <a class="header-anchor" href="#editing-an-entry" aria-label="Permalink to &quot;Editing an entry&quot;">​</a></h2><p>You need the entry ID (shown when it was logged, or from <code>get_time_entries</code>).</p><blockquote><p>&quot;Edit entry 42 — change to 4h&quot; &quot;Update entry 42 notes to &#39;Fixed header bug&#39;&quot;</p></blockquote><p>VERA rewrites the full entry row. Owners can edit any entry; Users can only edit their own.</p><hr><h2 id="deleting-an-entry" tabindex="-1">Deleting an entry <a class="header-anchor" href="#deleting-an-entry" aria-label="Permalink to &quot;Deleting an entry&quot;">​</a></h2><blockquote><p>&quot;Delete entry 42&quot;</p></blockquote><p>VERA will confirm the deletion. It is permanent — there is no undo.</p><hr><h2 id="viewing-your-time" tabindex="-1">Viewing your time <a class="header-anchor" href="#viewing-your-time" aria-label="Permalink to &quot;Viewing your time&quot;">​</a></h2><blockquote><p>&quot;What have I logged this week?&quot; &quot;Show my time for March&quot; &quot;How many hours have I logged on Nike?&quot;</p></blockquote><p>VERA filters entries by whatever combination of person, project, task, and date range you specify. Users only see their own entries; Managers and Owners can query across the team.</p><hr><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><p><strong>Project not found:</strong></p><blockquote><p>&quot;❌ Failed: Project not found. Similar projects: &#39;Nike Rebrand&#39;, &#39;Nike Campaign&#39;. Please use the exact name.&quot;</p></blockquote><p>Use the exact project name. If you&#39;re unsure, ask VERA to &quot;list projects&quot; first.</p><p><strong>Ambiguous task:</strong> If a task name matches multiple types, VERA will ask you to clarify.</p><p><strong>Permission denied:</strong> Users can only log for themselves. If you try to log for someone else:</p><blockquote><p>&quot;You can only log time for yourself.&quot;</p></blockquote><hr><h2 id="protected-time-off-projects" tabindex="-1">Protected time-off projects <a class="header-anchor" href="#protected-time-off-projects" aria-label="Permalink to &quot;Protected time-off projects&quot;">​</a></h2><p>You cannot log directly to &quot;Out of Office,&quot; &quot;Sick,&quot; or &quot;Leave&quot; projects. These require the formal request/approval flow. See <a href="/vera-docs/reference/workflows/time-off.html">Time Off Requests</a>.</p>',55)])])}const d=o(n,[["render",i]]);export{p as __pageData,d as default};
